package main

import (
	"bytes"
	"fmt"

	"gopkg.in/yaml.v3"
)

// mirror of internal/seed.topLevelMapping
func topLevelMapping(raw []byte) (*yaml.Node, bool) {
	dec := yaml.NewDecoder(bytes.NewReader(raw))
	var doc yaml.Node
	if err := dec.Decode(&doc); err != nil {
		return nil, false
	}
	var second yaml.Node
	if err := dec.Decode(&second); err == nil {
		return nil, false
	}
	if len(doc.Content) == 0 {
		return nil, false
	}
	root := doc.Content[0]
	if root.Kind != yaml.MappingNode {
		return nil, false
	}
	return root, true
}

func main() {
	cases := map[string]string{
		"plain":                  "name: x\nextra: 1\n",
		"trailing --- (empty 2nd doc)": "name: x\nextra: 1\n---\n",
		"trailing --- then blank":      "name: x\n---\n\n",
		"trailing --- then comment":    "name: x\n---\n# just a comment\n",
		"frontmatter md":               "---\nname: cr\ncolor: green\n---\n\n# Code Reviewer\n\nBody.\n",
		"frontmatter md no body":       "---\nname: cr\n---\n",
		"leading --- only":             "---\nname: x\nextra: 1\n",
		"two real docs":                "name: x\n---\nname: y\n",
		"garbage 2nd doc":              "name: x\n---\n\ta: [unclosed\n",
	}
	for k, v := range cases {
		_, ok := topLevelMapping([]byte(v))
		fmt.Printf("%-30s accepted=%v\n", k, ok)
	}

	// what does the second Decode actually return for the empty-2nd-doc case?
	for _, s := range []string{"name: x\n---\n", "---\nname: cr\n---\n", "name: x\n---\n# c\n"} {
		dec := yaml.NewDecoder(bytes.NewReader([]byte(s)))
		var a, b yaml.Node
		e1 := dec.Decode(&a)
		e2 := dec.Decode(&b)
		fmt.Printf("input=%q  err1=%v  err2=%v  b.Kind=%v b.Content=%d\n", s, e1, e2, b.Kind, len(b.Content))
	}
}

